// Cross-engine end-to-end suite for the Neodoc editor.
//
// The editor has three surfaces and only one of them can be tested by `node --test`:
// the page that runs from a `file://` URL (editor/neodoc-editor.html, generated by
// tools/bundle.js), the same page served by `neodoc serve`, and the degraded paths
// a fork or an older build has to take when optional browser APIs are missing.
// These specs drive all three through a real browser input stack.
//
// What each project stands for (brands and hardened forks share the engine):
//   chromium      → Chrome, Edge, Brave, Opera, Vivaldi, Arc (Blink + V8)
//   firefox       → Firefox, LibreWolf, Waterfox, Tor Browser (Gecko)
//   webkit        → Safari, every browser on iOS, GNOME Web (WebKit)
//   mobile-chrome → Android Blink at a phone viewport and DPR
//   mobile-safari → iOS WebKit at a phone viewport and DPR
//   chrome, edge  → the branded Blink builds the runner image ships, so the
//                   real Chrome/Edge binaries are tested, not our Chromium build
//
// API availability is where forks differ (Brave shields, Tor hardening, Firefox's
// missing File System Access API, older Safari without CompressionStream). That
// difference is covered by e2e/fallbacks.spec.js, which deletes those APIs before
// the page loads and asserts the degraded path in every engine.
//
// `npx playwright test` is the entry point; `npm run test:e2e` wraps it.

import { defineConfig, devices } from '@playwright/test';

// Branded builds are system binaries: Chrome/Edge are on the GitHub runner images
// and `channel` makes Playwright launch those, not the downloaded Chromium.
const branded = (device, channel) => ({ ...devices[device], channel });

export default defineConfig({
  testDir: './e2e',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  // A flaky pass hides an engine difference; keep failures visible and fix them.
  retries: 0,
  workers: process.env.CI ? 2 : undefined,
  reporter: [['list']],
  // Every page is a local file:// or http://127.0.0.1 URL; nothing is remote.
  timeout: 60_000,
  expect: { timeout: 15_000 },
  use: {
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
    // The fallbacks spec relies on the download path; keep it on for every project.
    acceptDownloads: true,
  },
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    { name: 'firefox', use: { ...devices['Desktop Firefox'] } },
    { name: 'webkit', use: { ...devices['Desktop Safari'] } },
    { name: 'mobile-chrome', use: { ...devices['Pixel 7'] } },
    { name: 'mobile-safari', use: { ...devices['iPhone 14'] } },
    { name: 'chrome', use: branded('Desktop Chrome', 'chrome') },
    { name: 'edge', use: branded('Desktop Edge', 'msedge') },
  ],
});
